<?php
session_start(); require __DIR__ . '/app/config/db_connection.php';
if (!isset($_SESSION['admin_id'])) { header('Location:admin_login.php'); exit; }
$canteens=$conn->query('SELECT id,canteen_name FROM canteens ORDER BY canteen_name'); $cid=(int)($_GET['canteen_id']??0); $status=$_GET['status']??''; $date=$_GET['date']??'';
$where=' WHERE 1=1'; $types=''; $params=[];
if($cid){$where.=' AND o.canteen_id=?';$types.='i';$params[]=$cid;}
if(in_array($status,['pending','preparing','completed','cancelled'],true)){$where.=' AND LOWER(o.status)=?';$types.='s';$params[]=$status;}
if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$where.=' AND DATE(o.created_at)=?';$types.='s';$params[]=$date;}
$q=$conn->prepare("SELECT o.id,o.total,o.status,o.created_at,o.payment_method,o.payment_status,s.full_name student,c.canteen_name FROM orders o JOIN students s ON s.id=o.student_id JOIN canteens c ON c.id=o.canteen_id $where ORDER BY o.id DESC LIMIT 100"); if($params)$q->bind_param($types,...$params); $q->execute(); $orders=$q->get_result();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order Oversight | UniCanteen</title><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@600;700&family=Poppins:wght@400;600&display=swap" rel="stylesheet"><style>:root{--blue:#2563eb;--muted:#64748b}*{box-sizing:border-box}body{margin:0;padding:24px;font:14px Poppins,sans-serif;background:#f1f5f9;color:#0f172a}.top,.card{background:#fff;border-radius:12px;box-shadow:0 2px 10px #0000000d}.top{padding:18px 22px;margin-bottom:18px}.top h1{margin:0;font:700 21px Montserrat}.top p{margin:5px 0 0;color:var(--muted);font-size:13px}.filter{display:flex;flex-wrap:wrap;gap:9px;margin-top:15px}.filter select,.filter input,.filter button,.clear{padding:9px 11px;border-radius:7px;font:inherit}.filter select,.filter input{border:1px solid #cbd5e1;background:#fff;min-width:165px}.filter button{border:0;background:var(--blue);color:#fff;font-weight:600;cursor:pointer}.clear{border:1px solid #cbd5e1;background:#fff;color:#334155;text-decoration:none;font-weight:600}.card{padding:18px;overflow:auto}table{width:100%;min-width:750px;border-collapse:collapse}th,td{text-align:left;padding:11px 8px;border-bottom:1px solid #e2e8f0;font-size:13px}th{color:var(--muted);font-size:12px}.pill{display:inline-block;padding:4px 8px;border-radius:20px;background:#e2e8f0;text-transform:capitalize;font-size:12px}.pending{background:#fef3c7}.preparing{background:#dbeafe;color:#1d4ed8}.completed{background:#dcfce7;color:#166534}.cancelled{background:#fee2e2;color:#b91c1c}@media(max-width:600px){body{padding:14px}.filter>*{width:100%}}</style></head><body><section class="top"><h1>Order Oversight</h1><p>Review orders by canteen, status, or date. Clearing filters only resets this view; it never deletes orders.</p><form class="filter" method="get"><select name="canteen_id"><option value="0">All canteens</option><?php while($c=$canteens->fetch_assoc()):?><option value="<?=$c['id']?>" <?=$cid===$c['id']?'selected':''?>><?=htmlspecialchars($c['canteen_name'])?></option><?php endwhile?></select><select name="status"><option value="">All statuses</option><?php foreach(['pending','preparing','completed','cancelled'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=ucfirst($x)?></option><?php endforeach?></select><input type="date" name="date" value="<?=htmlspecialchars($date)?>" aria-label="Order date"><button type="submit">Apply filters</button><a class="clear" href="admin_orders.php">Clear filters</a></form></section><section class="card"><table><thead><tr><th>Order</th><th>Student</th><th>Canteen</th><th>Total</th><th>Payment</th><th>Status</th><th>Created</th></tr></thead><tbody><?php while($o=$orders->fetch_assoc()):?><tr><td><b>#<?=$o['id']?></b></td><td><?=htmlspecialchars($o['student'])?></td><td><?=htmlspecialchars($o['canteen_name'])?></td><td>PHP <?=number_format($o['total'],2)?></td><td><?=($o['payment_method']==='gcash_sandbox'?'GCash':'Cash')?> <small>(<?=htmlspecialchars($o['payment_status'])?>)</small></td><td><span class="pill <?=strtolower($o['status'])?>"><?=htmlspecialchars($o['status'])?></span></td><td><?=htmlspecialchars($o['created_at'])?></td></tr><?php endwhile?></tbody></table></section></body></html>
